window.BOOK={"key":"wardiyya","app":"mutoon-wardiyya","lsk":"mutoon_wardiyya_v1","prefix":"wa_","title":"لامية ابن الوردي","sub":"نصيحة الإخوان ومرشدة الخلان · زين الدين عمر ابن الوردي (ت ٧٤٩هـ) · ٧٧ بيتًا","poems":[{"id":"wardiyya","title":"لامية ابن الوردي","nazim":"زين الدين أبو حفص عمر بن مظفر بن عمر ابن الوردي المعري","death":"ت ٧٤٩هـ","meter":"الرمل","source":"جامع الكتب الإسلامية: العرف الندي في تخميس لامية ابن الوردي للملاح، تحقيق د. جميل عبد الله عويضة (١٤٣١هـ)","srcUrl":"https://ketabonline.com/ar/books/57150","note":"لا توجد نسخة رقمية مشكولة كاملة. اللفظ من أبيات اللامية في تخميس الملاح المحقق على مخطوطتين، وقوبل كلمةً كلمةً بسكربت على نسخة «الديوان» ونشرة الحجوري المقابلة على نسخ وأبيات شرح الطريفي. وفي مواضع الخلاف أُخذ ما عليه أكثر النسخ وشرح «فتح الرحيم الرحمن» (ط ١٢٩٨هـ). الشكل مجموع من هذه النسخ وهي مشكولة جزئيًا، وأُكمل الباقي بما لا يحتمل غيره لغةً ووزنًا، والمواضع المشكلة في تقرير المصادر.","verses":[["اعْتَزِلْ ذِكْرَ الْأَغَانِي وَالْغَزَلْ","وَقُلِ الْفَصْلَ وَجَانِبْ مَنْ هَزَلْ"],["وَدَعِ الذِّكْرَى لِأَيَّامِ الصِّبَا","فَلِأَيَّامِ الصِّبَا نَجْمٌ أَفَلْ"],["إِنَّ أَهْنَى عِيشَةٍ قَضَّيْتُهَا","ذَهَبَتْ لَذَّاتُهَا وَالْإِثْمُ حَلّ"],["وَاتْرُكِ الْغَادَةَ لَا تَحْفِلْ بِهَا","تُمْسِ فِي عِزٍّ وَتُرْفَعْ وَتُجَلّ"],["وَالْهَ عَنْ آلَةِ لَهْوٍ أَطْرَبَتْ","وَعَنِ الْأَمْرَدِ مُرْتَجِّ الْكَفَلْ"],["إِنْ تَبَدَّى تَنْكَسِفْ شَمْسُ الضُّحَى","وَإِذَا مَا مَاسَ يُزْرِي بِالْأَسَلْ"],["زَادَ إِنْ قِسْنَاهُ بِالْبَدْرِ سَنًا","أَوْ عَدَلْنَاهُ بِغُصْنٍ فَاعْتَدَلْ"],["وَافْتَكِرْ فِي مُنْتَهَى حُسْنِ الَّذِي","أَنْتَ تَهْوَاهُ تَجِدْ أَمْرًا جَلَلْ"],["وَاهْجُرِ الْخَمْرَةَ إِنْ كُنْتَ فَتًى","كَيْفَ يَسْعَى فِي جُنُونٍ مَنْ عَقَلْ"],["وَاتَّقِ اللَّهَ فَتَقْوَى اللَّهِ مَا","جَاوَرَتْ قَلْبَ امْرِئٍ إِلَّا وَصَلْ"],["لَيْسَ مَنْ يَقْطَعُ طُرْقًا بَطَلًا","إِنَّمَا مَنْ يَتَّقِي اللَّهَ الْبَطَلْ"],["صَدِّقِ الشَّرْعَ وَلَا تَرْكَنْ إِلَى","رَجُلٍ يَرْصُدُ بِاللَّيْلِ زُحَلْ"],["حَارَتِ الْأَفْكَارُ فِي قُدْرَةِ مَنْ","قَدْ هَدَانَا سُبُلًا عَزَّ وَجَلّ"],["كَتَبَ الْمَوْتَ عَلَى الْخَلْقِ فَكَمْ","فَلَّ مِنْ جَيْشٍ وَأَفْنَى مِنْ دُوَلْ"],["أَيْنَ نُمْرُودُ وَكَنْعَانُ وَمَنْ","مَلَكَ الْأَرْضَ وَوَلَّى وَعَزَلْ"],["أَيْنَ عَادٌ أَيْنَ فِرْعَوْنُ وَمَنْ","رَفَعَ الْأَهْرَامَ مَنْ يَسْمَعْ يَخَلْ"],["أَيْنَ مَنْ سَادُوا وَشَادُوا وَبَنَوْا","هَلَكَ الْكُلُّ وَلَمْ تُغْنِ الْقُلَلْ"],["أَيْنَ أَرْبَابُ الْحِجَا أَهْلُ النُّهَى","أَيْنَ أَهْلُ الْعِلْمِ وَالْقَوْمُ الْأُوَلْ"],["سَيُعِيدُ اللَّهُ كُلًّا مِنْهُمُ","وَسَيَجْزِي فَاعِلًا مَا قَدْ فَعَلْ"],["أَيْ بُنَيَّ اسْمَعْ وَصَايَا جَمَعَتْ","حِكَمًا خُصَّتْ بِهَا خَيْرُ الْمِلَلْ"],["اطْلُبِ الْعِلْمَ وَلَا تَكْسَلْ فَمَا","أَبْعَدَ الْخَيْرَ عَلَى أَهْلِ الْكَسَلْ"],["وَاحْتَفِلْ لِلْفِقْهِ فِي الدِّينِ وَلَا","تَشْتَغِلْ عَنْهُ بِمَالٍ أَوْ خَوَلْ"],["وَاهْجُرِ النَّوْمَ وَحَصِّلْهُ فَمَنْ","يَعْرِفِ الْمَطْلُوبَ يَحْقِرْ مَا بَذَلْ"],["لَا تَقُلْ قَدْ ذَهَبَتْ أَرْبَابُهُ","كُلُّ مَنْ سَارَ عَلَى الدَّرْبِ وَصَلْ"],["فِي ازْدِيَادِ الْعِلْمِ إِرْغَامُ الْعِدَى","وَجَمَالُ الْعِلْمِ إِصْلَاحُ الْعَمَلْ"],["جَمِّلِ الْمَنْطِقَ بِالنَّحْوِ فَمَنْ","يُحْرَمِ الْإِعْرَابَ بِالنُّطْقِ اخْتَبَلْ"],["انْظُمِ الشِّعْرَ وَلَازِمْ مَذْهَبِي","فَاطِّرَاحُ الرِّفْدِ فِي الدُّنْيَا أَقَلّ"],["فَهْوَ عُنْوَانٌ عَلَى الْفَضْلِ وَمَا","أَحْسَنَ الشِّعْرَ إِذَا لَمْ يُبْتَذَلْ"],["مَاتَ أَهْلُ الْفَضْلِ لَمْ يَبْقَ سِوَى","مُقْرِفٍ أَوْ مَنْ عَلَى الْأَصْلِ اتَّكَلْ"],["أَنَا لَا أَخْتَارُ تَقْبِيلَ يَدٍ","قَطْعُهَا أَجْمَلُ مِنْ تِلْكَ الْقُبَلْ"],["إِنْ جَزَتْنِي عَنْ مَدِيحِي صِرْتُ فِي","رِقِّهَا أَوْ لَا فَيَكْفِينِي الْخَجَلْ"],["أَعْذَبُ الْأَلْفَاظِ قَوْلِي لَكَ خُذْ","وَأَمَرُّ اللَّفْظِ نُطْقِي بِلَعَلّ"],["مُلْكُ كِسْرَى عَنْهُ تُغْنِي كِسْرَةٌ","وَعَنِ الْبَحْرِ اجْتِزَاءٌ بِالْوَشَلْ"],["اعْتَبِرْ نَحْنُ قَسَمْنَا بَيْنَهُمْ","تَلْقَهُ حَقًّا وَبِالْحَقِّ نَزَلْ"],["لَيْسَ مَا يَحْوِي الْفَتَى مِنْ عَزْمِهِ","لَا وَلَا مَا فَاتَ يَوْمًا بِالْكَسَلْ"],["اطْرَحِ الدُّنْيَا فَمِنْ عَادَاتِهَا","تَخْفِضُ الْعَالِي وَتُعْلِي مَنْ سَفَلْ"],["عِيشَةُ الزَّاهِدِ فِي تَحْصِيلِهَا","عِيشَةُ الْجَاهِدِ بَلْ هَذَا أَذَلّ"],["كَمْ جَهُولٍ وَهْوَ مُثْرٍ مُكْثِرٌ","وَعَلِيمٍ مَاتَ مِنْهَا بِالْعِلَلْ"],["كَمْ شُجَاعٍ لَمْ يَنَلْ مِنْهَا الْمُنَى","وَجَبَانٍ نَالَ غَايَاتِ الْأَمَلْ"],["فَاتْرُكِ الْحِيلَةَ فِيهَا وَاتَّئِدْ","إِنَّمَا الْحِيلَةُ فِي تَرْكِ الْحِيَلْ"],["أَيُّ كَفٍّ لَمْ تُفِدْ مِمَّا تُفَدْ","فَرَمَاهَا اللَّهُ مِنْهُ بِالشَّلَلْ"],["لَا تَقُلْ أَصْلِي وَفَصْلِي أَبَدًا","إِنَّمَا أَصْلُ الْفَتَى مَا قَدْ حَصَلْ"],["قَدْ يَسُودُ الْمَرْءُ مِنْ غَيْرِ أَبٍ","وَبِحُسْنِ السَّبْكِ قَدْ يُنْفَى الزَّغَلْ"],["وَكَذَا الْوَرْدُ مِنَ الشَّوْكِ وَمَا","يَطْلُعُ النَّرْجِسُ إِلَّا مِنْ بَصَلْ"],["مَعَ أَنِّي أَحْمَدُ اللَّهَ عَلَى","نَسَبِي إِذْ بِأَبِي بَكْرِ اتَّصَلْ"],["قِيمَةُ الْإِنْسَانِ مَا يُحْسِنُهُ","أَكْثَرَ الْإِنْسَانُ مِنْهُ أَوْ أَقَلّ"],["اكْتُمِ الْأَمْرَيْنِ فَقْرًا وَغِنًى","وَاكْسِبِ الْفَلْسَ وَحَاسِبْ مَنْ بَطَلْ"],["وَادَّرِعْ جِدًّا وَكَدًّا وَاجْتَنِبْ","صُحْبَةَ الْحَمْقَى وَأَرْبَابِ الْبَخَلْ"],["بَيْنَ تَبْذِيرٍ وَبُخْلٍ رُتْبَةٌ","وَكِلَا هَذَيْنِ إِنْ زَادَ قَتَلْ"],["لَا تَخُضْ فِي سَبِّ سَادَاتٍ مَضَوْا","إِنَّهُمْ لَيْسُوا بِأَهْلٍ لِلزَّلَلْ"],["وَتَغَافَلْ عَنْ أُمُورٍ إِنَّهُ","لَمْ يَفُزْ بِالْحَمْدِ إِلَّا مَنْ غَفَلْ"],["لَيْسَ يَخْلُو الْمَرْءُ مِنْ ضِدٍّ وَإِنْ","حَاوَلَ الْعُزْلَةَ فِي رَأْسِ جَبَلْ"],["مِلْ عَنِ النَّمَّامِ وَاهْجُرْهُ فَمَا","بَلَّغَ الْمَكْرُوهَ إِلَّا مَنْ نَقَلْ"],["دَارِ جَارَ الدَّارِ إِنْ جَارَ وَإِنْ","لَمْ تَجِدْ صَبْرًا فَمَا أَحْلَى النُّقَلْ"],["جَانِبِ السُّلْطَانَ وَاحْذَرْ بَطْشَهُ","لَا تُخَاصِمْ مَنْ إِذَا قَالَ فَعَلْ"],["لَا تَلِ الْحُكْمَ وَإِنْ هُمْ سَأَلُوا","رَغْبَةً فِيكَ وَخَالِفْ مَنْ عَذَلْ"],["إِنَّ نِصْفَ النَّاسِ أَعْدَاءٌ لِمَنْ","وَلِيَ الْأَحْكَامَ هَذَا إِنْ عَدَلْ"],["فَهْوَ كَالْمَحْبُوسِ عَنْ لَذَّاتِهِ","وَكِلَا كَفَّيْهِ فِي الْحَشْرِ تُغَلّ"],["إِنَّ لِلنَّقْصِ وَالِاسْتِثْقَالِ فِي","لَفْظَةِ الْقَاضِي لَوَعْظًا وَمَثَلْ"],["لَا تُوَازَى لَذَّةُ الْحُكْمِ بِمَا","ذَاقَهُ الشَّخْصُ إِذَا الشَّخْصُ انْعَزَلْ"],["فَالْوِلَايَاتُ وَإِنْ طَابَتْ لِمَنْ","ذَاقَهَا فَالسُّمُّ فِي ذَاكَ الْعَسَلْ"],["نَصَبُ الْمَنْصِبِ أَوْهَى جَلَدِي","وَعَنَائِي مِنْ مُدَارَاةِ السَّفلْ"],["قَصِّرِ الْآمَالَ فِي الدُّنْيَا تَفُزْ","فَدَلِيلُ الْعَقْلِ تَقْصِيرُ الْأَمَلْ"],["إِنَّ مَنْ يَطْلُبُهُ الْمَوْتُ عَلَى","غِرَّةٍ مِنْهُ جَدِيرٌ بِالْوَجَلْ"],["غِبْ وَزُرْ غِبًّا تَزِدْ حُبًّا فَمَنْ","أَكْثَرَ التَّرْدَادَ أَضْنَاهُ الْمَلَلْ"],["خُذْ بِنَصْلِ السَّيْفِ وَاتْرُكْ غِمْدَهُ","وَاعْتَبِرْ فَضْلَ الْفَتَى دُونَ الْحُلَلْ"],["لَا يَضُرُّ الْفَضْلَ إِقْلَالٌ كَمَا","لَا يَضُرُّ الشَّمْسَ إِطْبَاقُ الطَّفَلْ"],["حُبُّكَ الْأَوْطَانَ عَجْزٌ ظَاهِرٌ","فَاغْتَرِبْ تَلْقَ عَنِ الْأَهْلِ بَدَلْ"],["فَبِمُكْثِ الْمَاءِ يَبْقَى آسِنًا","وَسُرَى الْبَدْرِ بِهِ الْبَدْرُ اكْتَمَلْ"],["أَيُّهَا الْعَائِبُ قَوْلِي عَبَثًا","إِنَّ طِيبَ الْوَرْدِ مُؤْذٍ بِالْجُعَلْ"],["عَدِّ عَنْ أَسْهُمِ لَفْظِي وَاسْتَتِرْ","لَا يُصِيبَنَّكَ سَهْمٌ مِنْ ثُعَلْ"],["لَا يَغُرَّنَّكَ لِينٌ مِنْ فَتًى","إِنَّ لِلْحَيَّاتِ لِينًا يُعْتَزَلْ"],["أَنَا مِثْلُ الْمَاءِ سَهْلٌ سَائِغٌ","وَمَتَى سُخِّنَ آذَى وَقَتَلْ"],["أَنَا كَالْخَيْزُورِ صَعْبٌ كَسْرُهُ","وَهْوَ لَدْنٌ كَيْفَمَا شِئْتَ انْفَتَلْ"],["غَيْرَ أَنِّي فِي زَمَانٍ مَنْ يَكُنْ","فِيهِ ذَا مَالٍ هُوَ الْمَوْلَى الْأَجَلّ"],["وَاجِبٌ عِنْدَ الْوَرَى إِكْرَامُهُ","وَقَلِيلُ الْمَالِ فِيهِمْ يُسْتَقَلّ"],["كُلُّ أَهْلِ الْعَصْرِ غمْرٌ وَأَنَا","مِنْهُمُ فَاتْرُكْ تَفَاصِيلَ الْجُمَلْ"]],"secs":{"1":"المنظومة"}}],"sharh":false};
